unless questions.map { |q| q.fetch(:question_number) } == (1..20).to_a
  raise "模擬試験46は問1〜20の20問で構成してください"
end
expected_categories = ["education_foundations", "education_foundations", "education_system", "education_system", "education_system", "curriculum_organization", "curriculum_organization", "integrated_inquiry", "moral_education", "special_activities", "student_guidance_career", "special_support_education", "educational_psychology", "educational_psychology", "education_system", "information_specialized", "information_education", "information_specialized", "information_specialized", "information_specialized"]
expected_blank_counts = { 3 => 4, 4 => 4, 5 => 4, 6 => 4, 7 => 4, 8 => 4, 9 => 4, 10 => 4, 11 => 3, 16 => 3, 17 => 4, 18 => 3 }
unless questions.map { |q| q.fetch(:category_code) } == expected_categories
  raise "模擬試験46の分類または順序が不正です"
end
expected_legal_prompts = { 4 => "次の各文は，「学校教育法」（昭和22年法律第26号）の条文である。文章中の空欄 ① ～ ④ に当てはまる語句の組合せとして正しいものを下のア～エの中から一つ選んで記号で答えなさい。", 5 => "次の各文は，「教育公務員特例法」 （昭和24年法律第1号）の条文である。文章中の空欄 ① ～ ④ に当てはまる語句の組合せとして正しいものを下のア～エの中から一つ選んで記号で答えなさい。" }
questions.each do |question|
  number = question.fetch(:question_number)
  blocks = question.fetch(:content_blocks)
  if expected_legal_prompts.key?(number) && blocks.first.fetch(:text) != expected_legal_prompts.fetch(number)
    raise "問#{number}の導入は指定の法令問題文に統一してください"
  end
  choices = question.fetch(:choices)
  unless question.fetch(:major_category_code) == (number <= 15 ? "teacher_education" : "information") &&
      choices.map { |c| c.fetch(:label) } == %w[ア イ ウ エ] && choices.count { |c| c.fetch(:correct) } == 1 &&
      choices.map { |c| c.fetch(:content_blocks) }.uniq.size == 4
    raise "問#{number}の分類・四択・正答が不正です"
  end
  unless %w[ア イ ウ エ].all? { |label| question.fetch(:explanation_blocks).any? { |b| b[:text]&.start_with?("#{label}：") } }
    raise "問#{number}に全肢解説が必要です"
  end
  unless question.fetch(:source_text).lines.any? && question[:source_text].lines.all? { |line| line.strip.match?(/\A.+ \| https:\/\/\S+\z/) }
    raise "問#{number}の出典形式が不正です"
  end
  quotes = blocks.select { |b| b[:type] == "fill_in_quote" }
  labels = blocks.flat_map { |b| b.fetch(:text, "").scan(/\{\{([^{}]+)\}\}/).flatten }.uniq.sort
  count = expected_blank_counts[number]
  if count
    expected = %w[① ② ③ ④].first(count)
    body_labels = if number == 19
      blocks.select { |b| b[:type] == "code" }.flat_map { |b| b[:code].scan(/【([^】]+)】/).flatten }.uniq.sort
    elsif number == 11 && false
      blocks.select { |b| b[:type] == "table" }.flat_map { |b| (b[:headers] + b[:rows].flatten).join.scan(/【([^】]+)】/).flatten }.uniq.sort
    else
      quotes.flat_map { |b| b.fetch(:text).scan(/\{\{([^{}]+)\}\}/).flatten }.uniq.sort
    end
    unless blocks.first[:type] == "fill_in_text" && labels == expected && body_labels == expected &&
        choices.all? { |c| c[:content_blocks].size == 1 && c[:content_blocks].first[:type] == "fill_in_choice" && c[:content_blocks].first[:cells].size == count }
      raise "問#{number}の必須空欄・選択肢セルの対応が不正です"
    end
    choices.map { |c| c[:content_blocks].first[:cells] }.transpose.each do |column|
      raise "問#{number}の空欄候補は各列2対2にしてください" unless column.tally.values.sort == [2, 2]
    end
  elsif labels.any? || choices.any? { |c| c[:content_blocks].any? { |b| b[:type] == "fill_in_choice" } }
    raise "問#{number}に想定外の空欄があります"
  end
  if [4, 5].include?(number) && !quotes.all? { |b| b[:text].match?(/\A第\d+条/) }
    raise "問#{number}の抜粋枠は条番号から始めてください"
  end
  if [6, 7].include?(number)
    clause = number == 6 ? "第3款" : "第5款"
    unless blocks.first[:text].include?(clause) && question[:source_text].include?(clause)
      raise "問#{number}の出典範囲が不正です"
    end
  end
  blocks.select { |b| ["code", "table"].include?(b[:type]) }.each do |b|
    raise "表・コードの空欄は【①】等で表示してください" if b.values.flatten.join.include?("{{")
  end
end
unless questions.map { |q| q[:choices].find { |c| c[:correct] }[:label] }.tally == %w[ア イ ウ エ].to_h { |l| [l, 5] }
  raise "模擬試験46の正答位置は各5件にしてください"
end
QuestionSeedSync.import(exam_number: 46, questions: questions, publication_status: "published")
